class DenseSplitContinuityTest{public static void main(String[]args){var w=RiverSplitGeometryTest.world(512,0,0);var original=w.environment.water.clone();var height=w.height.clone();var split=RiverFlow.split(100,new RiverFlow.Arm(4,4,.01,.028),new RiverFlow.Arm(4,1.5,.01,.06));var bar=new RiverRibbon.SedimentIsland(256,256,20,2,0);var plan=new RiverFlow.BranchPlan(split,90,6,3,true);RiverRibbon.island(w,0,0,62,bar,plan);int retained=0;for(int z=0;z<512;z++)for(int x=0;x<512;x++){int i=z*512+x;if(original[i]<=Math.round(height[i])){if(w.environment.waterY(i,62)>Math.round(w.height[i]))throw new AssertionError("Dense split added an isolated side puddle");continue;}double shape=Math.pow((x-256)/20.,2)+Math.pow((z-256)/2.,2);if(shape<=1)continue;if(w.environment.waterY(i,62)<=Math.round(w.height[i]))throw new AssertionError("Dense split clipped curved parent water");retained++;}if(w.environment.waterY(256*512+256,62)>Math.round(w.height[256*512+256]))throw new AssertionError("Island center was flooded");System.out.println("PASS: dense split preserves all "+retained+" original wet blocks outside its dry island");}}
